<?php

declare(strict_types=1);

namespace LEDSpicerTools\MameCredits;

/**
 * Writes credits.dat from the verified successes of one MAME version.
 *
 * An entry is one or more "set:" lines, then its "key=value" lines, ended by a blank line.
 * Sets with identical lines share an entry. "@family:" entries hold the counter BIOS families share
 * once Hints::PROMOTE parents agree; a member using it says "family=<name>" instead of "credits=".
 */
final class Dat {

	public const HEADER = <<<'TXT'
		; credits.dat, generated by mame-credits (LEDSpicer-Tools), MIT license.
		; Data from the tool's own discovery on %s.
		;
		; credits[N]=cpu,space,address,size,encoding  credit counter (N per player when credits are per player)
		;   space "share": cpu is a memory share tag and address an offset in it (a memory mapper moves it)
		;   space "ram": cpu is a RAM device tag and address an offset in it (memory a CPU installs at startup)
		;   encoding: bin, bcd, any (bin or bcd, never seen above 9), digits / digits_le (one decimal digit per byte)
		; family=name        the credits of the @name: entry
		; start_mode=        input (start input after a credit), coin (the coin starts), coin_buys_play
		; startN=input,cost  input that starts player N and the credits it takes
		; auto_start=yes     the game also starts by itself (a start timer)
		; coinage=           coins/credits per coin slot, at the default settings
		; dips=kind=port/mask,...  switches to report at launch: freeplay, coinage, coin_<slot>, cabinet, coin_slots, players

		TXT;

	/**
	 * @param array<string, array<string, string>> $rows results rows keyed by set.
	 * @param array<string, Machine> $machines
	 */
	public static function write(string $path, array $rows, array $machines, string $build): void {
		$rows     = array_filter($rows, fn(array $row): bool => $row['status'] === Status::Success->value && $row['verified'] === 'yes');
		$families = self::families($rows, $machines);
		$entries  = [];
		foreach ($rows as $set => $row) {
			$lines  = self::lines($row);
			$family = $families[$row['family']] ?? null;
			if ($family !== null && $lines[0] === $family)
				$lines[0] = "family={$row['family']}";
			$entries[implode("\n", $lines)][] = $set;
		}
		$content = sprintf(self::HEADER, $build) . "\n";
		foreach ($families as $name => $credits)
			$content .= "@$name:\n$credits\n\n";
		uasort($entries, fn(array $a, array $b): int => strcmp($a[0], $b[0]));
		foreach ($entries as $lines => $sets)
			$content .= implode(":\n", $sets) . ":\n$lines\n\n";
		file_put_contents($path, $content);
	}

	/**
	 * Credits line of each BIOS family whose parents agree on one, keyed by family.
	 *
	 * @return array<string, string>
	 */
	private static function families(array $rows, array $machines): array {
		$votes = [];
		foreach ($rows as $set => $row) {
			$family = $machines[$row['family']] ?? null;
			if ($family !== null && $family->isBios && $machines[$set]->cloneof === '')
				$votes[$family->name][self::lines($row)[0]][] = $set;
		}
		$families = [];
		foreach ($votes as $name => $byCredits) {
			uasort($byCredits, fn(array $a, array $b): int => count($b) <=> count($a));
			if (count(reset($byCredits)) >= Hints::PROMOTE)
				$families[$name] = key($byCredits);
		}
		ksort($families);
		return $families;
	}

	/**
	 * Entry lines of a row, the credits line first.
	 *
	 * @return string[]
	 */
	private static function lines(array $row): array {
		$addresses = explode('|', $row['address']);
		$lines     = [];
		foreach ($addresses as $player => $address) {
			$key     = count($addresses) > 1 ? 'credits' . ($player + 1) : 'credits';
			$lines[] = "$key={$row['cpu']},{$row['space']},$address,{$row['size']},{$row['encoding']}";
		}
		$lines = [implode("\n", $lines), "start_mode={$row['start_mode']}"];
		foreach ([1, 2] as $player) {
			if ($row["start{$player}_field"] !== '')
				$lines[] = rtrim("start$player={$row["start{$player}_field"]},{$row["start{$player}_cost"]}", ',');
		}
		if ($row['auto_start'] === 'yes')
			$lines[] = 'auto_start=yes';
		$lines[] = "coinage={$row['coins_per_credit']}";
		if ($row['dips'] !== '')
			$lines[] = "dips={$row['dips']}";
		return $lines;
	}
}
